-- An implicit min-max index is generated by the server, so an ALIAS expression that cannot be analysed any more
-- (its dictionary is gone) must not prevent the table from being attached.

DROP TABLE IF EXISTS t_implicit_alias_dict;
DROP DICTIONARY IF EXISTS d_implicit_alias_dict;
DROP TABLE IF EXISTS t_implicit_alias_dict_src;

CREATE TABLE t_implicit_alias_dict_src (id UInt64, s String, n UInt64, d Date) ENGINE = Memory;
INSERT INTO t_implicit_alias_dict_src VALUES (1, 'a', 10, '2026-01-01'), (2, 'b', 20, '2026-01-02'), (3, 'c', 30, '2026-01-03');
CREATE DICTIONARY d_implicit_alias_dict (id UInt64, s String, n UInt64, d Date)
PRIMARY KEY id SOURCE(CLICKHOUSE(TABLE 't_implicit_alias_dict_src')) LAYOUT(FLAT()) LIFETIME(0);

CREATE TABLE t_implicit_alias_dict
(
    id UInt64,
    a_str String ALIAS dictGet('d_implicit_alias_dict', 's', id),
    a_num UInt64 ALIAS dictGet('d_implicit_alias_dict', 'n', id),
    a_date Date ALIAS dictGet('d_implicit_alias_dict', 'd', id)
)
ENGINE = MergeTree ORDER BY id
SETTINGS add_minmax_index_for_string_columns = 1, add_minmax_index_for_numeric_columns = 1, add_minmax_index_for_temporal_columns = 1;
INSERT INTO t_implicit_alias_dict VALUES (1), (2);
SELECT name FROM system.data_skipping_indices WHERE database = currentDatabase() AND table = 't_implicit_alias_dict' ORDER BY name;

DROP DICTIONARY d_implicit_alias_dict SETTINGS check_table_dependencies = 0;
DETACH TABLE t_implicit_alias_dict;
ATTACH TABLE t_implicit_alias_dict;
SELECT name FROM system.data_skipping_indices WHERE database = currentDatabase() AND table = 't_implicit_alias_dict' ORDER BY name;
SELECT id FROM t_implicit_alias_dict ORDER BY id;
INSERT INTO t_implicit_alias_dict VALUES (3);

CREATE DICTIONARY d_implicit_alias_dict (id UInt64, s String, n UInt64, d Date)
PRIMARY KEY id SOURCE(CLICKHOUSE(TABLE 't_implicit_alias_dict_src')) LAYOUT(FLAT()) LIFETIME(0);
DETACH TABLE t_implicit_alias_dict;
ATTACH TABLE t_implicit_alias_dict;
SELECT name FROM system.data_skipping_indices WHERE database = currentDatabase() AND table = 't_implicit_alias_dict' ORDER BY name;
-- The part inserted while the dictionary was missing is read once the dictionary is back.
SELECT id, a_str, a_num, a_date FROM t_implicit_alias_dict WHERE a_str = 'c';
SELECT id FROM t_implicit_alias_dict WHERE a_num >= 20 ORDER BY id;

DROP TABLE t_implicit_alias_dict;
DROP DICTIONARY d_implicit_alias_dict;
DROP TABLE t_implicit_alias_dict_src;
